import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Sprite mode: textured plane (512×320 px atlas → 1.6:1 aspect ratio)
  const width = 0.64;
  const height = 0.4;
  const geometry = new THREE.PlaneGeometry(width, height);

  // Load texture (synchronous, cached)
  const textureMap = ctx.textureLoader.load(config.imageUrl);

  // TSL material with texture node
  const colorNode = texture(textureMap, uv());
  const material = new MeshBasicNodeMaterial({
    colorNode,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Render text via fontAtlas
  if (ctx.fontAtlas && config.textContent) {
    const textMesh = ctx.fontAtlas.create({
      text: config.textContent.text || 'Features 3',
      fontSize: config.textContent.fontSize,
      font: 'Lora',
      fontWeight: config.textContent.fontWeight || 400,
      color: 0x16161d, // ink
    });
    if (textMesh) {
      textMesh.position.z = 0.01;
      group.add(textMesh);
    }
  }

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureMap.dispose();
  };

  return group;
}
